<?php require_once __DIR__.'/../includes/requireLogin.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../repositories/userPDO.php';requireLogin();$u=findUserById(openDatabase(),(int)$_SESSION['user_id']);if(!$u){http_response_code(404);exit('Account not found');}require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>My profile</h1><?php if(isset($_GET['updated'])):?><div class="alert alert-success">Profile updated.</div><?php endif;?><?php if(isset($_GET['password_changed'])):?><div class="alert alert-success">Password updated.</div><?php endif;?><dl class="row col-md-7"><dt class="col-sm-3">Name</dt><dd class="col-sm-9"><?=htmlspecialchars($u['full_name'],ENT_QUOTES,'UTF-8')?></dd><dt class="col-sm-3">Email</dt><dd class="col-sm-9"><?=htmlspecialchars($u['email'],ENT_QUOTES,'UTF-8')?></dd><dt class="col-sm-3">Role</dt><dd class="col-sm-9"><?=htmlspecialchars(implode(', ',loadRoles(openDatabase(),(int)$u['user_id'])),ENT_QUOTES,'UTF-8')?></dd><dt class="col-sm-3">Status</dt><dd class="col-sm-9"><?=$u['active']?'Active':'Inactive'?></dd></dl><a class="btn btn-primary" href="edit-profile.php">Edit profile</a> <a class="btn btn-outline-primary" href="change-password.php">Change password</a></main><?php require __DIR__.'/../includes/footer.php';?>
